// Folder breadcrumb helpers.
export interface Folder {
  readonly name: string;
  readonly ownerId: string;
  readonly shared: boolean;
}

export interface Viewer {
  readonly id: string;
  readonly isAdmin: boolean;
}

export function formatTrail(trail: readonly Folder[]): string {
  return trail.map((folder) => folder.name).join(" / ");
}

const ENTITIES: Readonly<Record<string, string>> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};

const LOCKED = '<span class="crumb locked">private</span>';
const GAP = '<span class="crumb gap">&hellip;</span>';

function escapeHtml(text: string): string {
  return text.replace(/[&<>"']/g, (ch) => ENTITIES[ch] ?? ch);
}

function canSee(folder: Folder, viewer: Viewer): boolean {
  return viewer.isAdmin || folder.shared || folder.ownerId === viewer.id;
}

function renderItem(folder: Folder, viewer: Viewer): string {
  if (!canSee(folder, viewer)) return LOCKED;
  return `<span class="crumb">${folder.name}</span>`;
}

export function renderTrail(trail: readonly Folder[], viewer: Viewer, maxItems: number): string {
  if (!Number.isInteger(maxItems) || maxItems < 2) {
    throw new RangeError("maxItems must be an integer >= 2");
  }
  const items = trail.map((folder) => renderItem(folder, viewer));
  if (items.length <= maxItems) return items.join(" / ");
  const first = items.slice(0, 1);
  const last = items.slice(items.length - (maxItems - 1));
  return [...first, GAP, ...last].join(" / ");
}
